'use strict';
// Motion runs only on intentional navigation; live data refreshes keep the page still.
let studioMotionPage=null;
function studioPageMotion(){if(S.busy||S.accountState==='checking')return;const page=[S.session?.user?.id,S.role,S.page,S.authMode].join(':');if(studioMotionPage===page)return;studioMotionPage=page;const main=$('main');if(!main?.animate||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;main.animate([{opacity:.5,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.2,.7,.2,1)'});}
function studioDialogMotion(){const modal=$('modal');if(!modal?.animate||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;modal.animate([{opacity:0,transform:'translateY(10px) scale(.985)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:200,easing:'cubic-bezier(.2,.7,.2,1)'});}
function cooperativeOverview(){const members=scoped(S.profiles).filter(p=>!p.archived_at&&p.registration_kind!=='Staff'&&!directoryAssignment(p)),requests=currentMemberRequests(),balances=S.financials.filter(f=>members.some(p=>p.id===f.member_id)),sum=field=>balances.reduce((n,f)=>n+(Number(f[field])||0),0),unit=S.role==='Admin'?'All districts':S.role==='DM'?'District '+S.assignment.district:bn(S.assignment.branch_id)+' branch',newMembers=members.filter(p=>p.membership_status==='Pending verification').length,edits=requests.filter(q=>q.kind==='Profile edit'&&['Pending','BM approved'].includes(q.status)).length,syncs=requests.filter(q=>q.kind==='Financial sync'&&['Pending','BM approved'].includes(q.status)).length;
 const queues=S.role==='Admin'?[['Staff applications',S.applications.filter(a=>a.status==='Pending').length,"S.teamTab='Applications';go('Team')",'users'],['Member records',newMembers,"go('New Members')",'user'],['Financial records',syncs,"go('Financial sync')",'wallet']]:[['New members',newMembers,"go('New Members')",'user'],['Information edits',edits,"go('Approvals')",'shield'],['Actual balance reviews',syncs,"go('Financial sync')",'wallet']];
 const recent=scoped(S.audit).slice().sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)||Number(b.id)-Number(a.id)).slice(0,5),capitalVerified=balances.filter(f=>f.share_capital!==null&&f.share_capital!==undefined).length;
 return heading('Workspace overview',e(roleLabel(S.role))+' · '+e(unit))+`<div class="grid four">${metric('Active members',members.filter(p=>p.membership_status==='Active').length,'Verified cooperative memberships')}${metric('New members',newMembers,'Awaiting branch and district screening')}${metric('Information edits',edits,'Requests within your operating units')}${metric('Financial reviews',syncs,'BM screening and final DM review')}</div><div class="studio-overview"><section class="card"><span class="studio-kicker">Cooperative accounts</span><h2>Verified balances</h2><div class="studio-balance-grid"><div><span>Savings</span><strong>${money(sum('savings'))}</strong></div><div><span>Outstanding loans</span><strong>${money(sum('loan_balance'))}</strong></div><div><span>Share capital</span><strong>${capitalVerified?money(sum('share_capital')):'Not verified'}</strong></div></div><p class="smalltext">${balances.length} member records in your current operating units. Share capital includes ${capitalVerified} verified opening balances.</p></section><section class="card"><span class="studio-kicker">Current workspace</span><h2>Queue status</h2><ul class="studio-queue">${queues.map(([label,count,action,symbol])=>`<li><button type="button" onclick="${action}">${icon(symbol)}<span>${e(label)}</span><b class="portal-count ${count?'has-pending':''}">${count}</b>${icon('down')}</button></li>`).join('')}</ul></section><section class="card studio-activity"><div class="card-head"><div><span class="studio-kicker">Recorded work</span><h2>Latest workspace activity</h2></div>${button('View activity',"go('Activity')",'outline small','clock')}</div>${recent.length?`<ul class="studio-recent">${recent.map(a=>`<li><span class="iconbox">${icon('clock')}</span><div><strong>${e(a.action||'Workspace activity')}</strong><small>${e(a.actor_name||S.profiles.find(p=>p.id===a.actor_id)?.full_name||'Cooperative record')}${a.actor_role?' · '+e(roleLabel(a.actor_role)):''}</small></div><time>${e(financeRecordedTime(a.created_at))}</time></li>`).join('')}</ul>`:empty('No recorded activity yet','New work in your operating units will appear here.')}</section></div>`;
}
